INSERT OR IGNORE INTO documents (id, kind, slug, status, body_json, updated_at, updated_by) VALUES ('doc-agency', 'agency', 'agency', 'published', '{"name": "Forever Memories Travel", "eyebrow": "Colorado Springs travel agency", "footerLine": "We plan family vacations, theme parks, cruises, and international trips from Colorado Springs."}', '2026-10-29T00:00:00Z', 'seed');
INSERT OR IGNORE INTO documents (id, kind, slug, status, body_json, updated_at, updated_by) VALUES ('doc-intro', 'agency', 'intro', 'published', '{"heading": "Thoughtfully planned journeys that last forever.", "lede": "Personalized travel planning, expert guidance, and unforgettable experiences for every kind of traveler."}', '2026-10-29T00:00:00Z', 'seed');
INSERT OR IGNORE INTO documents (id, kind, slug, status, body_json, updated_at, updated_by) VALUES ('doc-vacations', 'section', 'vacations', 'published', '{"kicker": "Family vacations", "heading": "The trip fits the family, not the other way around.", "body": "Family travel works when the plan follows who is coming, how you like to spend a day, and what you want to skip. The plan follows that, from the first night to the ride home."}', '2026-10-29T00:00:00Z', 'seed');
INSERT OR IGNORE INTO documents (id, kind, slug, status, body_json, updated_at, updated_by) VALUES ('doc-parks', 'section', 'parks', 'published', '{"kicker": "Theme parks", "heading": "Disney and Orlando days with room to breathe.", "body": "A Disney visit or another Orlando park day needs tickets, a park order, and time between the gates. The castle can be the whole point, or one piece of a longer trip."}', '2026-10-29T00:00:00Z', 'seed');
INSERT OR IGNORE INTO documents (id, kind, slug, status, body_json, updated_at, updated_by) VALUES ('doc-cruises', 'section', 'cruises', 'published', '{"kicker": "Cruises", "heading": "The ship, the ports, and the week between them.", "body": "We sort the cruise, the cabin style, and which ports are worth leaving the ship for. You get a week that is planned before you board. A cruise can stand on its own or follow a few days in Orlando."}', '2026-10-29T00:00:00Z', 'seed');
INSERT OR IGNORE INTO documents (id, kind, slug, status, body_json, updated_at, updated_by) VALUES ('doc-international', 'section', 'international', 'published', '{"kicker": "International travel", "heading": "Farther from home, still a clear plan.", "body": "Passports, pacing, and a route that matches the group. International trips stay specific to the people traveling, not a generic tour."}', '2026-10-29T00:00:00Z', 'seed');
INSERT OR IGNORE INTO documents (id, kind, slug, status, body_json, updated_at, updated_by) VALUES ('doc-step-1', 'step', '1', 'published', '{"title": "You write.", "body": "Who is going, what kind of trip, and when you hope to leave.", "order": 1}', '2026-10-29T00:00:00Z', 'seed');
