INSERT OR IGNORE INTO documents (id, kind, slug, status, body_json, updated_at, updated_by) VALUES ('doc-step-3', 'step', '3', 'published', '{"title": "You go.", "body": "The request you send here is the start of that conversation.", "order": 3}', '2026-10-29T00:00:00Z', 'seed');
